window.POETRY_REGISTER("v5-strict-9-10-0-6f0a906af3ea.js",{"poems":[[22503,2],[25872,2],[52729,2],[52961,2],[55705,2],[87108,7],[94417,7],[109551,7],[114126,7],[116512,7],[116979,7],[120020,7],[136921,7],[136929,7],[140225,7],[143395,7],[155919,7],[176453,7],[182247,7],[189230,7],[192122,7],[193734,7],[203470,7],[233405,7],[236780,7],[238528,7],[241271,7],[271969,7],[272122,7],[272149,7],[274568,7],[288119,7],[293618,7],[299355,7],[301582,7],[301808,7],[307127,7],[317146,7],[337659,9],[347193,9],[359691,9],[368169,10],[368191,10],[399427,8],[402029,8],[402297,8],[415399,8],[422254,8],[425741,8],[453354,8],[453910,8],[458102,8],[461537,8],[462444,8],[499399,8],[499914,8],[519319,8],[524926,8],[531079,8],[532525,8],[540583,8],[545954,8],[550212,8],[550216,8],[550574,8],[551956,8],[570792,8],[573750,8],[596197,8],[614714,8],[621261,8],[624750,8],[629296,8],[648953,5],[650074,5],[653286,5],[661817,5],[707695,5],[720605,5],[725206,5],[734683,5]],"pairs":[["天雨曼陀罗花深没膝","四十千真珠璎珞堆高楼",0],["上无臯陶伯益廊庙材","的不能匡君辅国活生民",1],["下无巢父许由箕颍操","又不能食薇饮水自苦辛",1],["元和十二载八月解化","瘗于天柱山大涤洞东北",2],["大历中唱和五十七人","元本不注姓名于联句下",3],["意滂必文彩风流之士","当时之民被和平之化矣",4],["知我者谓我高蹈世表","不知我者谓我下视尘窟",5],["客当西归乃东去为何","欲及八月十五夜观洪涛",6],["崭岩崷崪兮磅礴无垠","巄嵸嵂勃兮宁一以为仁",7],["昔闻汲黯淮阳亦如此","乃不及舞文巧诋为诈忠",8],["一女二夫兮妾之所羞","不忠于所事兮其将何求",9],["夫何不幸兮人之云亡","谁司有命兮付与之不长",10],["提壶秉笔兮酣咏其侧","花神有知兮得不留心哉",11],["时雨霖兮忽若海潦收","无事兮我以观万物之情",12],["窃悲吾子之多暇日兮","愁嗟黄落如郢客之见秋",13],["椒香桂绿兮云车满野","敬谢有功兮宜奠于泉下",14],["吾之将归兮星律回秋","告邦人兮导畎浍之常流",14],["必未厌我乞醯与借马","但只恐勤君赤脚与露头",15],["譬如戴天履地于终日","而其高明深厚所不能知",16],["其在今兹则还报王事","秣马脂车与离长安之日",17],["知我者谓我深锥痛札","不知我者谓我吊影扬鞭",18],["屈身辱志兮恨何时雪","誓速归泉下兮此愁可绝",19],["以弱为强兮以予为取","边廷无犬吠兮息旗与鼓",20],["安得万里飘风一吹散","见巍峩苍翠解我心鬰陶",21],["朝霞为羞兮沆瀣为醴","瑶华玉馔兮错杂而陈前",22],["负罪囚奴兮九畴我保","庶汤孙之复兮载兴商道",23],["子从其父兮孙访吾祖","子志不遂兮孙之心良苦",24],["黄鹄脱骖兮素虬停驷","几弭节兮念遗民而来顾",25],["贵岂能玉余骨使莫腐","富岂能冰余肉使莫臭邪",26],["帖出于近世抚臣之家","又得以记先友于尝僚也",27],["窃以为夫君金缕之衣","亦未足以换墨练之裙也",28],["想公从容子墨客卿间","犹足以接六一之风流也",29],["拟师之道兮虚空钉橛","美师之德兮色重里胶青",30],["羌若人兮大带而深衣","张拱徐趋兮俨乎其若思",31],["笑把凌霄峰信脚踏翻","直得新昌石佛额头汗出",32],["君知云山云山亦知君","是之谓行其庭不见其人",33],["谁知醉无以将还自愧","终不如独醒君子赋离骚",34],["橐有金兮盍专为母驰","心悦桑女下车兮人可知",35],["得马祖百丈黄檗之旨","发自己胸中本有底光明",36],["委骨草莽兮时廼天命","自古孰无死兮首丘为正",37],["除琴剑又别无珍共宝","只一片至诚心要也不要",38],["呜呼民生衣食惟粟帛","独不念灵光殿古梁栋折",39],["上山而笑兮下而钓鱼","岂如他人兮唯富贵之求",40],["上通帝座二气之呼吸","下冲龙门百折之昆仑源",41],["便从炼师乞浆啖火枣","青华定录共共见茅君盈",42],["却原来姹紫嫣红开遍","似这般都付与断井颓垣",43],["起看灯花已落油已干","始知是电耳非关灯之残",44],["愿为分背交颈之逸足","不愿为追风绝景之霜蹄",45],["下有蛟龙兮海波横流","谁使子来兮从伯氏以游",46],["古有虞帝奏韶之遗石","乃在庾岭之南曲江之侧",47],["岂无牡丹妆点春富贵","又何似天绣芙蓉出清泚",48],["嗟乎人生何不共努力","君不见城鸦哺子忽生翼",49],["金章紫绶不可以幸致","如君者谓非历块之龙媒",50],["宁为地上特生之野草","不能为茂树负岩墙而居",51],["愿为楚女巫山之行雨","不愿作甄妃洛浦之凌波",52],["濮山㟪崔兮濮水漻泬","高贤愉愉兮繄孝而烈穆",53],["汉武帝时有一暴公子","自称直指使者来治齐鲁",54],["得非扬州观头逢七七","又何必善和坊里延端端",55],["吾闻白水之崖高硉矹","飞流若虹兮奔遄而飘忽",56],["我有芙蓉三尺剑赠之","归来兮昆丘蓬海之仙山",57],["齐州九点苍茫若可辨","吴阊匹练指碧空而惊猜",58],["安得昌容之仙授我诀","服食二百有馀岁完天和",59],["吁嗟画工有此大奇手","又何必攀藤缘磴探泽薮",60],["含情欲诉兮怀羞复止","魂荡泆而不禁兮竟为痴",61],["何必瑶池王母歌白云","又何必交梨火枣与玉斧",62],["他时更祝南山为君颂","可但是来往乾坤在十洲",63],["中宵弹剑歌来魂欲销","愁绝是万户沉沉风电骄",64],["有女娲取而炼以补之","所馀者青玄赤白皆分别",65],["山有湫云蓊郁风飕飕","乃在章贡之阳崆峒之幽",66],["吾闻句漏仙翁之丹井","乃在紫微之阳东山之顶",67],["得非尤物自有鬼神护","无乃好事者摸拟希其伦",68],["汉武帝时有一暴公子","自称直指使者来治齐鲁",69],["嗟乎人生何不共努力","君不见城鸦哺子忽生翼",70],["安得昌容之仙授我诀","服食二百有馀岁完天和",71],["濮山㟪崔兮濮水漻泬","高贤愉愉兮繄孝而烈穆",72],["妾思纵横陈海唱弯弧","君不得相思树下多明星",73],["爬爬屋三间当了大殿","衮龙袍穿这一领大布衫",74],["天下无不读书之神仙","亦无读书不饮酒之神仙",75],["祇今穹碑蚀残龙凤字","犹来披榛剥藓寻幽宫帝",76],["我生不得骑马游司并","又不得披裘冰天射虎行",77],["欲辞骨月兮莫闻吾声","存不离保姆兮殁乃独行",78],["不用纪功勒石铭燕然","亦不用短衣射虎消残年",79],["妾思纵横陈海唱弯弧","君不得相思树下多明星",80]]});
